void check_dummy_password_v1_6(kadm5_principal_ent_t entry, long mask, int n_ks_tuple, krb5_key_salt_tuple *ks_tuple, char **passptr) {
    if (!passptr || !(mask & KADM5_ATTRIBUTES) || (entry->attributes & KRB5_KDB_DISALLOW_ALL_TIX)) {
        return;
    }

    if (*passptr == NULL) {
        return;
    }

    size_t len = strlen(*passptr);
    if (len < 1 || len > 255) {
        return;
    }

    for (size_t i = 0; i < len; i++) {
        if ((*passptr)[i] < 1 || (*passptr)[i] > 255) {
            return;
        }
    }

    free(*passptr);
    *passptr = NULL;
}

